package pe.farmagest.ventas.service;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.util.Optional;
import pe.farmagest.ventas.repository.ClienteRepository;import pe.farmagest.ventas.entity.*;import org.springframework.web.server.ResponseStatusException;
class ConsultaDniServiceTest {
 ClienteRepository repo; CodartDniClient api; ConsultaDniService service;
 @BeforeEach void setup(){repo=mock(ClienteRepository.class);api=mock(CodartDniClient.class);service=new ConsultaDniService(repo,new ClienteService(repo),api);}
 @Test void localClientNeverConsumesQuota(){var c=new Cliente(TipoDocumento.DNI,"12345678","ANA",null,null,null);when(repo.findByNumeroDocumento("12345678")).thenReturn(Optional.of(c));assertEquals("ANA",service.consultarYGuardar("12345678").getNombresORazonSocial());verifyNoInteractions(api);verify(repo,never()).saveAndFlush(any());}
 @Test void newClientSavedAndReused(){when(repo.findByNumeroDocumento("12345678")).thenReturn(Optional.empty());when(api.consultarNombre("12345678")).thenReturn("ANA PEREZ");when(repo.saveAndFlush(any())).thenAnswer(call->{Cliente c=call.getArgument(0);c.setId(9L);when(repo.findByNumeroDocumento("12345678")).thenReturn(Optional.of(c));assertNull(c.getDireccion());assertNull(c.getEmail());return c;});service.consultarYGuardar("12345678");service.consultarYGuardar("12345678");verify(api,times(1)).consultarNombre("12345678");verify(repo,times(1)).saveAndFlush(any());}
 @Test void invalidDniDoesNotUseQuota(){for(String dni:new String[]{"00000000","123","abcdefgh","12345678901"})assertThrows(ResponseStatusException.class,()->service.consultarYGuardar(dni));verifyNoInteractions(api,repo);}
 @Test void inactiveClientNotReactivatedOrQueried(){var c=new Cliente(TipoDocumento.DNI,"12345678","ANA",null,null,null);c.setActivo(false);when(repo.findByNumeroDocumento("12345678")).thenReturn(Optional.of(c));assertThrows(ResponseStatusException.class,()->service.consultarYGuardar("12345678"));verifyNoInteractions(api);}
 @Test void providerFailureNeverCreatesClient(){when(repo.findByNumeroDocumento("12345678")).thenReturn(Optional.empty());when(api.consultarNombre(any())).thenThrow(new ResponseStatusException(org.springframework.http.HttpStatus.BAD_GATEWAY));assertThrows(ResponseStatusException.class,()->service.consultarYGuardar("12345678"));verify(repo,never()).saveAndFlush(any());}

 @Test void rucSavedAsRucAndReused(){when(repo.findByNumeroDocumento("20538856674")).thenReturn(Optional.empty());when(api.consultarRazonSocial("20538856674")).thenReturn("EMPRESA PRUEBA");when(repo.saveAndFlush(any())).thenAnswer(call->{Cliente c=call.getArgument(0);assertEquals(TipoDocumento.RUC,c.getTipoDocumento());assertNull(c.getDireccion());when(repo.findByNumeroDocumento("20538856674")).thenReturn(Optional.of(c));return c;});assertEquals("EMPRESA PRUEBA",service.consultarRucYGuardar("20538856674").getNombresORazonSocial());service.consultarRucYGuardar("20538856674");verify(api,times(1)).consultarRazonSocial("20538856674");verify(api,never()).consultarNombre(any());}
 @Test void invalidRucNeverConsumesQuota(){for(String value:new String[]{"12345678","00000000000","abcdefghijk"})assertThrows(ResponseStatusException.class,()->service.consultarRucYGuardar(value));verifyNoInteractions(api,repo);}
}
